def parse_row(line: str) -> list[str]:
    result = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            if in_quotes:
                # Found an unescaped quote, so the previous field ends here
                current_field += char
                in_quotes = False
            else:
                # Start of a new quoted field
                in_quotes = True
                current_field = ""
        elif char == ',' and not in_quotes:
            result.append(current_field.strip())
            current_field = ""
        else:
            current_field += char

    # Don't forget the last field if it's not empty
    if current_field.strip():
        result.append(current_field.strip())

    return result
```

