import re

def parse_money(s: str) -> float | None:
    # Strip the '$' if present at the beginning
    s = s.strip('$')

    # Remove thousands separators (keep commas as delimiters)
    s = re.sub(r'\d{3}(,\d{3})*', '', s)

    # Try to parse the remaining string as a float
    try:
        return float(s)
    except ValueError:
        return None

    # Also handle cases where there's no '$' but it might be an invalid number like "n/a"
    if not s or 'n/a' in s.lower():
        return None
